import os
import torch


class Config:
    """
    Configuration parameters for the Image Denoising Task.
    Focuses on Idea 1: Plain Multi-Layer Convolutional Network (Flat-CNN).
    """

    # --- General Settings ---
    SEED = 42

    # --- Directories ---
    INPUT_DIR = "./input"
    METADATA_DIR = "./metadata"
    WORKING_DIR = "./working"

    # Output directories
    IDEA_DIR = os.path.join(WORKING_DIR, "idea_3")
    SUBMISSION_DIR = "./submission"

    # --- File Paths ---
    # Metadata files generated by the provided script
    TRAIN_METADATA_PATH = os.path.join(METADATA_DIR, "train.csv")
    VAL_METADATA_PATH = os.path.join(METADATA_DIR, "val.csv")
    TEST_METADATA_PATH = os.path.join(METADATA_DIR, "test.csv")

    # Model artifacts and submission
    MODEL_SAVE_PATH = os.path.join(IDEA_DIR, "unet_model.pth")
    SUBMISSION_PATH = os.path.join(SUBMISSION_DIR, "submission.csv")

    # --- Data Processing Hyperparameters ---
    PATCH_SIZE = (
        96  # Increased to support deeper network (Cite solution_lesson_node_00007)
    )
    NUM_WORKERS = 4  # Number of subprocesses for data loading

    # --- Model Hyperparameters ---
    # Specific to the Flat-CNN architecture
    CNN_HIDDEN_CHANNELS = 64
    CNN_NUM_LAYERS = 4
    CNN_KERNEL_SIZE = 3

    # --- Training Hyperparameters ---
    BATCH_SIZE = 64  # Reduced to maintain memory stability with larger patches (Cite solution_lesson_node_00007)
    LEARNING_RATE = 1e-3  # Standard starting rate for Adam
    EPOCHS = 100  # Max epochs (relies on early stopping)
    EARLY_STOPPING_PATIENCE = 10

    # --- Debugging / Development ---
    # Parameters to control dataset size for quick debugging runs
    DEBUG = False
    DEBUG_SUBSET_SIZE = 50  # Number of samples to use if DEBUG is True

    # --- Hardware ---
    DEVICE = "cuda" if torch.cuda.is_available() else "cpu"

    @classmethod
    def setup(cls):
        """
        Ensures that the necessary working and submission directories exist.
        """
        os.makedirs(cls.IDEA_DIR, exist_ok=True)
        os.makedirs(cls.SUBMISSION_DIR, exist_ok=True)


# Execute setup upon import to guarantee directory existence
Config.setup()
